# Si aun asi se pasa del tope, se sueltan BLOQUES ENTEROS entre separadores '### ' en orden
# inverso (del ultimo al primero), nunca lineas sueltas: partir un bloque parte una funcion
# a la mitad (evidencia 101525). La cabecera, la ley y "a quien puede danar" son LO
# NECESARIO, no se tocan. Si el bloque del archivo nombrado no cabe, se conserva aunque se
# pase del tope.
def _bloques_desde(lineas):
    bs = []
    i = 0
    while i < len(lineas):
        if lineas[i].startswith("### "):
            j = i + 1
            while j < len(lineas) and not lineas[j].startswith("### "):
                j += 1
            bs.append(lineas[i:j])
            i = j
        else:
            i += 1
    return bs
necesarios = list(bloques["__cabecera__"])
for k in (ley, dana):
    if k and k != "__cabecera__":
        necesarios += bloques[k]
if len("\n".join(salida)) > tope:
    # Se separa lo necesario de lo prescindible conservando el orden original.
    prescindibles = [ln for ln in salida if ln not in necesarios]
    conservados = []
    for b in _bloques_desde(prescindibles):
        if archivo and any(archivo in ln for ln in b):
            conservados.append(b)
    for b in reversed(_bloques_desde(prescindibles)):
        if len("\n".join(necesarios + [ln for bb in conservados for ln in bb])) <= tope:
            break
        if b in conservados:
            continue
        conservados = [bb for bb in conservados if bb is not b]
    salida = necesarios + [ln for bb in conservados for ln in bb]
return "\n".join(salida)

